    if(type==='rele-termico')return 'FR';
    if(registryDefinition(type)?.behavior?.type==='interface-relay'||type==='rele-falta-fase'||type==='rele-auxiliar'||type==='temporizador'||type==='rele-estrela-triangulo'||type==='temporizador-estrela-triangulo'||type==='rele-biestavel-impulso')return 'KA';
    if(type.startsWith('botoeira-')||type.startsWith('chave-')||type.startsWith('botao-emergencia')||type==='fim-curso'||type==='pressostato'||type==='boia-nivel')return 'S';
    if(type.startsWith('sinaleiro-'))return 'H';
    if(type.startsWith('motor-')||type.startsWith('bomba-'))return 'M';
    if(type.startsWith('borne-'))return 'X';
