    if(['inversor-frequencia','inversor-delta-ms300','inversor-provolt-pi550'].includes(type))return 'INV';
    if(type.startsWith('fonte-')||type==='fonte-24vcc'||type==='transformador-comando')return 'PS';
    if(type==='multimetro-digital')return 'MM';
    if(registryDefinition(type)?.behavior?.type==='measurement-instrument')return 'MI';
    if(registryDefinition(type)?.behavior?.type==='microcontroller')return 'MCU';
    const registryBehaviorType=registryDefinition(type)?.behavior?.type||'';
    if(['earth-reference','earth-bus'].includes(registryBehaviorType))return 'PE';
    if(['ac-source','dc-source','ac-dc-power-supply','transformer'].includes(registryBehaviorType))return 'PS';
    if(registryBehaviorType==='relay-module'||registryBehaviorType==='relay-module-multi')return 'KR';
    if(['mosfet-n-channel','npn-transistor'].includes(registryBehaviorType))return 'Q';
    if(registryBehaviorType==='optocoupler')return 'U';
    if(registryBehaviorType==='driver-array')return 'IC';
    if(registryBehaviorType==='analog-multiplexer')return 'MUX';
    if(registryBehaviorType==='analog-sensor')return 'SEN';
    if(registryBehaviorType==='logic-peripheral')return 'MOD';
    if(registryBehaviorType==='modbus-rtu-io')return 'RIO';
    if(registryBehaviorType==='visual-module')return 'HMI';
    if(registryBehaviorType==='pump-system')return 'PB';
