  const conveyorIssueCommand=(component,command,notifyUser=true)=>{if(!component)return false;if(command==='auto'){component.dataset.conveyorMode='auto';component.dataset.conveyorAutoCycle='true';component.dataset.conveyorDemand='true';if(notifyUser)notify('Esteiras em modo AUTO')}else if(command==='start'){component.dataset.conveyorMode='manual';component.dataset.conveyorAutoCycle='false';component.dataset.conveyorFault='false';component.dataset.conveyorDemand='true';if(notifyUser)notify('Comando START enviado às esteiras')}else if(command==='stop'){component.dataset.conveyorMode='manual';component.dataset.conveyorAutoCycle='false';component.dataset.conveyorDemand='false';if(notifyUser)notify('Comando STOP enviado às esteiras')}else if(command==='reset'){component.dataset.conveyorFault='false';component.dataset.conveyorDemand='false';if((component.dataset.conveyorMode||'auto')==='auto')component.dataset.conveyorAutoCycle='true';if(notifyUser)notify('Falha resetada no sistema de esteiras')}else if(command==='jam'){const next=component.dataset.conveyorFault!=='true';component.dataset.conveyorFault=String(next);if(next){component.dataset.conveyorDemand='false';playMachineEffect('conveyor.jam')}if(notifyUser)notify(next?'Falha / travamento simulado':'Falha liberada')}conveyorRender(component);scheduleElectricalRecalc?.();return true};
