  const craneIssueCommand=(component,command,notifyUser=true)=>{if(!component)return false;const f=craneFlags(component);if(command==='auto'){component.dataset.craneMode='auto';component.dataset.craneAutoCycle='true';component.dataset.craneMotion='right';component.dataset.craneAutoStage='right';notifyUser&&notify('Ponte rolante em modo AUTO')}else if(command==='stop'){const was=component.dataset.craneMotion||'stopped';component.dataset.craneMode='manual';component.dataset.craneAutoCycle='false';component.dataset.craneMotion='stopped';if(was!=='stopped'){stopMachineSound(component);playMachineEffect('crane.stop')}notifyUser&&notify('Ponte rolante parada')}else if(command==='load'){component.dataset.craneLoadAttached=String(component.dataset.craneLoadAttached==='false');playMachineEffect('crane.alert');notifyUser&&notify(component.dataset.craneLoadAttached==='false'?'Carga removida':'Carga conectada')}else if(['left','right','up','down'].includes(command)){component.dataset.craneMode='manual';component.dataset.craneAutoCycle='false';if((command==='left'&&f.left)||(command==='right'&&f.right)||(command==='up'&&f.up)||(command==='down'&&f.down)){component.dataset.craneMotion='stopped';notifyUser&&notify('Fim de curso atingido')}else{component.dataset.craneMotion=command;notifyUser&&notify(`Comando ${command.toUpperCase()} enviado`)}}craneRender(component);scheduleElectricalRecalc?.();return true};
