  const applyPcf8574G17V14Preset=(created)=>{if(!created)return;const esp=created.get('esp'),pcf=created.get('pcf'),relay=created.get('kr'),button=created.get('s1');if(esp){let program=null;try{program=JSON.parse(esp.dataset.logicProgram||'null')}catch{};esp.dataset.logicManualMode='false';if(program?.pinModes)writeGpioModes(esp,program.pinModes);delete esp.dataset.i2cGpioMasterProgram;delete esp.dataset.gpioManualOverrides;writeGpioInputStates(esp,{});writeLogicRuntime(esp,{memory:{...(program?.memory||{})},previousInputs:{}});esp.dataset.i2cLogicRuntime=JSON.stringify({memory:{...(program?.memory||{})},previous:{}});esp.techribRefreshLogicControls?.()}if(pcf){for(const key of ['i2cGpioLatch','i2cGpioPinModes','i2cGpioPins','i2cGpioStatus','i2cGpioLastRead','i2cGpioConnected','i2cGpioFault'])delete pcf.dataset[key]}if(relay){relay.dataset.relayActiveLow='true';relay.dataset.relayChannels='{}';relay.dataset.logicPowered='false'}if(button)button.classList.remove('pressed');requestAnimationFrame(()=>{esp?.techribRefreshLogicControls?.();redrawWires();scheduleElectricalRecalc()})};

