  const examplePresentationV17=example=>{const technical=String(example?.name||example?.id||'Exemplo').trim();let title=String(exampleBenefitTitlesV17[String(example?.id||'')]||'').trim();if(!title)title=technical.replace(/^(?:ESP32(?: DevKit)?|Arduino(?: UNO| Mega 2560)?|Raspberry Pi Pico|KNX(?: TP1)?|DALI-2(?: DT8)?|Modbus RTU|RS485|Matter\/Thread|LoRa SX1278|Zigbee CC2530|CAN\/TWAI|TechRib 32 Relés|Teste|Quadro [A-Z]+|Delta MS300|Provolt PI550)\s*[—-]\s*/u,'').replace(/\s*[•·]\s*G\d+(?:\s+V[\d.]+)?\s*$/u,'').trim();return{title:title||technical,technical}};
  const exampleCategoryOrder=exampleTaxonomy.categories.map(category=>[category.id,category.label,category.icon,example=>example.categories?.includes(category.id)]);
  const managedStandardCategoryOptions=exampleTaxonomy.categories.map(category=>[category.id,category.label,category.icon]);
  const managedPremiumCategoryOptions=managedStandardCategoryOptions.map(item=>[...item]);
