  const populateCardCopy=(card,example,meta,icon)=>{const presentation=examplePresentationV17(example);card.querySelector('.example-card-icon').textContent=icon||exampleTaxonomy.meta?.(meta.primaryCategory)?.icon||'▤';card.querySelector('.example-card-copy>b').textContent=presentation.title;const technical=card.querySelector('.example-card-tech');if(technical){technical.textContent=presentation.technical!==presentation.title?presentation.technical:'';technical.hidden=presentation.technical===presentation.title}const accessBadge=card.querySelector('[data-example-access-badge]'),levelBadge=card.querySelector('[data-example-level-badge]');accessBadge.textContent=meta.access==='premium'?'Premium':'';accessBadge.hidden=meta.access!=='premium';accessBadge.dataset.access=meta.access;levelBadge.textContent=exampleTaxonomy.levelLabel(meta.level);levelBadge.dataset.level=meta.level};
  const createExampleCard=(example,icon)=>{const meta=exampleTaxonomy.classify(example),card=document.createElement('button');card.type='button';card.className='example-card';fillCardMetadata(card,example,meta);card.innerHTML=cardCopyMarkup();populateCardCopy(card,example,meta,icon);if(canEditStandardExamples){const remove=card.querySelector('i');remove.textContent='×';remove.dataset.deleteOfficialExample='true';remove.title='Excluir este exemplo';remove.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();deleteOfficialExample(example)})}card.addEventListener('click',event=>{if(event.target.closest('[data-delete-official-example]'))return;selectCardsForExample(example.id);openExample(example)});return card};
