    component.nets.forEach(n=>{const p=nodePos.get(n);if(!p)return;const isRail=n===left||n===right;if(isRail){const ys=placed.filter(z=>z.e.na===n||z.e.nb===n).map(z=>z.y);const y1=Math.min(y0+55,...ys)-28,y2=Math.max(y0+h-45,...ys)+28;v48Line(g,p.x,y1,p.x,y2,'v48-control-wire');const label=sourceInfo.get(n)?.label;if(label)v48Label(g,p.x,y1-12,label,'v48-terminal')}else if((degree.get(n)||0)>1)v48Dot(g,p.x,p.y,4)});
