    byRecord.forEach(list=>{if(list.length<2)return;const xs=list.map(z=>z.cx),top=Math.max(y0+40,Math.min(...list.map(z=>z.y))-72);v48Line(g,Math.min(...xs),top,Math.max(...xs),top,'v48-net-guide');list.forEach(z=>v48Line(g,z.cx,top,z.cx,z.y-38,'v48-net-guide'));v48Label(g,(Math.min(...xs)+Math.max(...xs))/2,top-10,`${list[0].e.record.tag} • ${list.length} polos acoplados`,'v48-tag')});
