    const pairGroups=new Map();els.slice().sort((a,b)=>a.priority-b.priority).forEach(e=>{const da=depth.get(e.na)||0,db=depth.get(e.nb)||0,k=`${Math.min(da,db)}-${Math.max(da,db)}`;if(!pairGroups.has(k))pairGroups.set(k,[]);pairGroups.get(k).push(e)});
    const maxLane=Math.max(0,...[...pairGroups.values()].map(v=>v.length-1)),bottomY=Math.min(y0+h-35,mainY+maxLane*92+120);
    allNets.forEach(n=>{const x=xOf(n),isRail=n===left||n===right;v48Line(g,x,y0+78,x,bottomY,isRail?'v48-control-wire':'v48-net-guide');if(sourceInfo.has(n))v48Label(g,x,y0+67,sourceInfo.get(n).label,'v48-terminal')});
