      const span=Math.max(34,(rightX-leftX)/2-50);v48Line(g,leftX,y,cx-Math.min(48,span),y,'v48-control-wire');v48Image(g,e.symbol,cx,y,88,66);v48Line(g,cx+Math.min(48,span),y,rightX,y,'v48-control-wire');v48Dot(g,leftX,y,3);v48Dot(g,rightX,y,3);v48Label(g,cx,y+48,`${e.record.tag} ${e.a}-${e.b}`,'v48-tag');v48Label(g,cx,y+62,e.desc,'v48-desc');
