    unifilarText(svg,42,42,`Diagrama multifilar técnico — ${title}`,'unifilar-title').setAttribute('text-anchor','start');
    unifilarText(svg,42,64,'V48.4.7 • cabeçalhos internos alinhados','unifilar-subtitle').setAttribute('text-anchor','start');
    v48Line(svg,800,88,800,height-42,'v48-separator');

    // ---- COMANDO ----
    const cg=unifilarSvgEl('g');svg.appendChild(cg);
    v48Label(cg,105,112,'CIRCUITO DE COMANDO / FUNCIONAL','v48-section-title','start');
    const L=95,R=745,top=165,bottom=735;
    v48Line(cg,L,top,L,bottom,'v48-control-wire');
    v48Line(cg,R,top,R,bottom,'v48-control-wire');
    v48Label(cg,L,top-12,'L / +','v48-terminal');
    v48Label(cg,R,top-12,'N / COM','v48-terminal');

    // Um único bloco SS1 no comando, com três entradas funcionais.
    const blockX=650,blockY=365,blockW=130,blockH=250;
    const box=unifilarSvgEl('rect',{x:blockX-blockW/2,y:blockY-blockH/2,width:blockW,height:blockH,rx:6,class:'v48-device-box',fill:'#ffffff',stroke:'#0f172a','stroke-width':'2'});cg.appendChild(box);
    v48Label(cg,blockX,blockY-blockH/2+26,tag(ss)||'SS1','v48-tag');
    const blockDivider=unifilarSvgEl('line',{x1:blockX-blockW/2,y1:blockY-blockH/2+36,x2:blockX+blockW/2,y2:blockY-blockH/2+36,stroke:'#0f172a','stroke-width':'1.2'});cg.appendChild(blockDivider);
    v48Label(cg,blockX,blockY-blockH/2+55,'ENTRADAS DE COMANDO','v48-desc');
