    v48Label(pg,center,breakerY+78,tag(breaker)||'Q1','v48-tag');
    ['1','3','5'].forEach((lab,i)=>v48Label(pg,phaseX[i],breakerTop-9,lab,'v48-terminal'));
    ['2','4','6'].forEach((lab,i)=>v48Label(pg,phaseX[i],breakerBottom+17,lab,'v48-terminal'));

